    avatar: '/only_icon.png',
    verified: true,
    type: 'bot'
  }
}

export function meAccount(currentUser) {
  return {
    id: '__me',
    name: currentUser?.name || currentUser?.username || 'You',
    handle: currentUser?.username || 'you',
    avatar: currentUser?.avatar || null,
    verified: false,
